-- Core schema: batches, notifications, the transactional outbox and the status audit trail.
-- Primary keys are UUIDv7 generated by the application (time-ordered, index friendly).

CREATE TABLE batches (
    id              uuid        PRIMARY KEY,
    idempotency_key text        UNIQUE,
    request_hash    bytea,
    total_count     integer     NOT NULL CHECK (total_count BETWEEN 1 AND 1000),
    accepted_count  integer     NOT NULL CHECK (accepted_count >= 0),
    rejected_count  integer     NOT NULL CHECK (rejected_count >= 0),
    created_at      timestamptz NOT NULL DEFAULT now(),
    CHECK (accepted_count + rejected_count = total_count)
);

CREATE TABLE notifications (
    id                  uuid        PRIMARY KEY,
    batch_id            uuid        REFERENCES batches (id),
    idempotency_key     text        UNIQUE,
    request_hash        bytea,
    channel             text        NOT NULL CHECK (channel IN ('sms', 'email', 'push')),
    priority            text        NOT NULL CHECK (priority IN ('high', 'normal', 'low')),
    recipient           text        NOT NULL,
    content             text        NOT NULL,
    status              text        NOT NULL CHECK (status IN (
                                        'pending', 'queued', 'sending', 'sent',
                                        'retry_scheduled', 'permanently_failed', 'cancelled')),
    attempts            integer     NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts        integer     NOT NULL CHECK (max_attempts >= 1),
    last_error          text,
    -- Not unique: providers may return non-unique or static ids.
    provider_message_id text,
    correlation_id      text,
    scheduled_at        timestamptz,
    sending_started_at  timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    sent_at             timestamptz
);

-- List endpoint: newest first with (created_at, id) as the cursor, optionally filtered.
CREATE INDEX notifications_created_idx         ON notifications (created_at DESC, id DESC);
CREATE INDEX notifications_status_created_idx  ON notifications (status, created_at DESC, id DESC);
CREATE INDEX notifications_channel_created_idx ON notifications (channel, status, created_at DESC, id DESC);
CREATE INDEX notifications_batch_idx           ON notifications (batch_id) WHERE batch_id IS NOT NULL;
-- Reaper: find deliveries whose lease expired.
CREATE INDEX notifications_sending_idx         ON notifications (sending_started_at) WHERE status = 'sending';

-- Transactional outbox. A row is a request to dispatch a notification once available_at has passed;
-- it covers first sends, scheduled sends and retries. Rows are deleted when published.
CREATE TABLE outbox (
    id              bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    notification_id uuid        NOT NULL REFERENCES notifications (id) ON DELETE CASCADE,
    payload         jsonb       NOT NULL,
    available_at    timestamptz NOT NULL DEFAULT now(),
    created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX outbox_available_idx ON outbox (available_at);

-- Append-only audit trail of every status transition.
CREATE TABLE notification_events (
    id              bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    notification_id uuid        NOT NULL REFERENCES notifications (id) ON DELETE CASCADE,
    from_status     text,
    to_status       text        NOT NULL,
    reason          text,
    created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX notification_events_notification_idx ON notification_events (notification_id, created_at);
